const guestWinCard = state => {
  if (state.accountSession) return "";
  const gw = state.guestWin || { status: "idle" };
  if (gw.status === "idle") return `<div class="guest-win-card"><p class="eyebrow" style="color:var(--yellow)">Free trial</p><h3>Play one round, win Sparks ⚡</h3><p class="muted">No sign-in needed to try. Win and you'll have 3 minutes to grab your Sparks.</p><button class="btn btn-primary" id="guest-win-play">Play now →</button></div>`;
  if (gw.status === "playing") return `<div class="guest-win-card"><p class="muted"><span class="spinner"></span>Rolling…</p></div>`;
  if (gw.status === "won") return `<div class="guest-win-card guest-win-won"><p class="eyebrow" style="color:var(--yellow)">You won!</p><h3>${gw.sparksReward} Sparks ⚡</h3><p class="muted">Register a free account within <strong id="guest-win-timer">03:00</strong> to claim it.</p><button class="btn btn-primary" data-route="account">Claim now →</button></div>`;
  if (gw.status === "lost") return `<div class="guest-win-card"><p class="muted">Not a win this time — try again tomorrow.</p></div>`;
  if (gw.status === "expired") return `<div class="guest-win-card"><p class="muted">Your win expired. Come back tomorrow for another shot.</p></div>`;
  if (gw.status === "error") return `<div class="guest-win-card"><p class="muted">${escapeText(gw.message || "Couldn't play right now.")}</p></div>`;
  return "";
};
