const themePicker=state=>{const isPremium=Boolean(state.accountProfile?.profile?.is_premium),currentPattern=state.accountProfile?.profile?.theme_pattern||DEFAULT_PATTERN_ID,currentPalette=state.accountProfile?.profile?.theme_palette||DEFAULT_PALETTE_ID,palette=paletteById(currentPalette);return `<div class="field full"><label>Pattern</label><div class="theme-grid">${PATTERNS.map(pattern=>{const locked=pattern.premium&&!isPremium;return `<button type="button" class="theme-swatch${currentPattern===pattern.id?" selected":""}${locked?" locked":""}" data-pattern-select="${pattern.id}" ${locked?"disabled":""} style="--swatch-a:${palette.colors[0]};--swatch-b:${palette.colors[1]}" aria-label="${escapeText(pattern.name)}"><span class="theme-swatch-fill pattern-fill--${pattern.id}"></span>${locked?'<span class="theme-lock">🔒</span>':""}<small>${escapeText(pattern.name)}</small></button>`;}).join("")}</div><small class="muted">Free patterns for everyone. Some patterns need premium — any color can be paired with any pattern.</small></div><div class="field full"><label>Color</label><div class="theme-grid">${PALETTES.map(pal=>`<button type="button" class="theme-swatch${currentPalette===pal.id?" selected":""}" data-palette-select="${pal.id}" style="--swatch-a:${pal.colors[0]};--swatch-b:${pal.colors[1]}" aria-label="${escapeText(pal.name)}"><span class="theme-swatch-fill pattern-fill--${currentPattern}"></span><small>${escapeText(pal.name)}</small></button>`).join("")}</div><small class="muted">When you connect, your chat window border blends both people's colors.</small></div>`;};
const WOF_COLORS=["#ff5d3b","#ffb020","#2a9d5c","#2563eb","#a855f7","#e11d48","#0891b2"];
const wheelSegmentGradient=segments=>{
  const total=segments.reduce((sum,s)=>sum+s.weight_bp,0)||1;
  let acc=0;
  return `conic-gradient(${segments.map((s,i)=>{const from=acc/total*360;acc+=s.weight_bp;const to=acc/total*360;return `${WOF_COLORS[i%WOF_COLORS.length]} ${from.toFixed(3)}deg ${to.toFixed(3)}deg`;}).join(",")})`;
};
const wheelSegmentLabels=segments=>{
  const total=segments.reduce((sum,s)=>sum+s.weight_bp,0)||1;
  let acc=0;
  return segments.map(s=>{
    const from=acc/total*360;acc+=s.weight_bp;const to=acc/total*360;
    const mid=(from+to)/2;
    const short=s.label.split("(")[0].trim();
    return `<span class="wof-label" style="transform:translate(-50%,-50%) rotate(${mid.toFixed(3)}deg) translateY(-72px) rotate(${(-mid).toFixed(3)}deg)">${escapeText(short)}</span>`;
  }).join("");
};
const wheelRestingDegForLabel=(segments,label)=>{
  const total=segments.reduce((sum,s)=>sum+s.weight_bp,0)||1;
  let acc=0;
  for(const s of segments){const from=acc/total*360;acc+=s.weight_bp;const to=acc/total*360;if(s.label===label)return (360-(from+to)/2)%360;}
  return 0;
};
const wheelOfFortuneHtml=state=>{
  const segments=state.wheelOdds||[];
  if(!segments.length)return "";
  const spinning=Boolean(state.wheelSpinning);
  const pending=state.wheelPendingSpin;
  const settled=state.lastWheelSpin;
  const targetLabel=spinning?pending?.segment_label:settled?.segment_label;
  const wheelEndDeg=spinning&&targetLabel?6*360+wheelRestingDegForLabel(segments,targetLabel):0;
  const restingDeg=!spinning&&targetLabel?wheelRestingDegForLabel(segments,targetLabel):0;
  const dialStyle=spinning?`--wheel-end-deg:${wheelEndDeg}deg`:`transform:rotate(${restingDeg}deg)`;
  return `<div class="wof-wheel-outer"><div class="wof-pointer"></div><div class="wof-dial${spinning?" spinning":""}" style="background:${wheelSegmentGradient(segments)};${dialStyle}">${wheelSegmentLabels(segments)}</div><div class="wof-hub">${spinning?"…":targetLabel?escapeText(targetLabel):"🎡"}</div></div>`;
};
