  const roster=turnOrder.length?`<div class="saved-list" style="margin-top:10px">${turnOrder.map(id=>`<div>${LUDO_COLOR_EMOJI[LUDO_COLORS[colors[id]]]} ${id===state.partyParticipantId?"You":escapeText(peerHandle(id))}${forfeited.includes(id)?" (left)":""}${turnOrder[game.turnIndex]===id&&status==="playing"?" ← turn":""}</div>`).join("")}</div>`:"";
